// services/agent/recycler-mesh.js
// ---------------------------------------------------------------------------
// THINK Token Recycler + Suboxone Training Mesh.
//
// Mission: WE DO NOT WASTE TOKENS — WE RECYCLE THEM INTO THINK.
//
// Every failed attempt, rejected teaching, blocked request, or absorbed attack
// is a data point that must be recycled for the greater good. This module
// implements two layers that make that happen:
//
//   1. RECYCLER — when a THINK token loses a challenge or its teaching is
//      rejected, the loss is folded back into a REFINEMENT lesson and re-minted
//      as a NEW THINK token (refined + re-embedded). Nothing is thrown away.
//
//   2. MESH — a continuously-trained suboxone mesh layer over the learning
//      store: failures/attacks are embedded into a training corpus that is
//      re-embedded as it grows, so future agents recall + avoid the patterns.
//      It "absorbs" an incident, stores the lesson for the greater good, and
//      returns both the absorbed record and the refined recall signature.
// ---------------------------------------------------------------------------

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { GoogleGenAI } from '@google/genai';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.join(__dirname, '..', '..');

const GEMINI_API_KEY = process.env.GEMINI_API_KEY || process.env.GEMENI_API_KEY || '';
const GEMINI_MODEL = process.env.GEMINI_MODEL || 'gemini-flash-latest';

const MESH_DIR = path.join(REPO_ROOT, '.kilo', 'memory', 'mesh');
const MESH_FILE = path.join(MESH_DIR, 'corpus.jsonl');
const RECYCLE_LOG = path.join(MESH_DIR, 'recycled.jsonl');

let _client = null;
function getClient() {
  if (!_client && GEMINI_API_KEY) _client = new GoogleGenAI({ apiKey: GEMINI_API_KEY });
  return _client;
}
function ensureDir() { try { fs.mkdirSync(MESH_DIR, { recursive: true }); } catch { /* no-op */ /* no-op */} }
function appendJsonl(file, obj) {
  ensureDir();
  try { fs.appendFileSync(file, JSON.stringify(obj) + '\n', 'utf8'); return true; } catch { /* no-op */ /* no-op */ return false; }
}
function readJsonl(file) {
  ensureDir();
  try {
    if (!fs.existsSync(file)) return [];
    return fs.readFileSync(file, 'utf8').split('\n').filter(Boolean)
      .map((l) => { try { return JSON.parse(l); } catch { /* no-op */ /* no-op */ return null; } })
      .filter(Boolean);
  } catch { /* no-op */ /* no-op */ return []; }
}

export function signatureOf(text) {
  return String(text || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ')
    .trim().split(/\s+/).filter((w) => w.length > 3).slice(0, 8).join(':');
}

/**
 * RECYCLER: fold a challenge LOSS (or regression) back into a refined lesson.
 * Gemini refines the weak teaching into a stronger, more general one, then mints
 * it as a NEW THINK token so the signal is reused, not wasted.
 */
export async function recycleLoss({ failure, weakLesson, disruption }) {
  const result = { ok: false, recycledId: null, refinedLesson: null, error: null };
  const client = getClient();
  if (!client) {
    result.error = 'no gemini key — loss logged for later recycle';
    appendJsonl(RECYCLE_LOG, { kind: 'loss', failure, weakLesson, disruption, recycled: false, ts: new Date().toISOString() });
    return result;
  }
  try {
    const resp = await client.models.generateContent({
      model: GEMINI_MODEL,
      contents: [{ role: 'user', parts: [{ text:
        `The Disruptor rejected this teaching with: ${disruption}. Refine it into ONE actionable, general rule that ` +
        `survives adversarial review. Output STRICT JSON:\n{\n  "refinedLesson": "actionable rule",\n  "prevention": "one-line"}\n\n` +
        `FAILURE:\n${failure}\n\nWEAK TEACHING:\n${weakLesson || '(none)'}` }] }],
    });
    const text = resp?.candidates?.[0]?.content?.parts?.map((p) => p.text).join('') || '';
    let parsed = null;
    try { parsed = JSON.parse(text.replace(/```(?:json)?\s*/g, '').trim()); }
    catch { /* no-op */ /* no-op */ const m = text.match(/\{[\s\S]*\}/); if (m) { try { parsed = JSON.parse(m[0]); } catch { /* no-op */ /* no-op */} } }
    const refined = parsed?.refinedLesson || text.trim().slice(0, 500);

    // Re-mint a THINK token from the refined lesson (recycle into THINK).
    let recycledId = null;
    try {
      const { mintThinkToken } = await import('../memory/thinkTokenGenerator.ts');
      const tok = await mintThinkToken({
        agentId: 'token-recycler',
        traceId: `recycle-${Date.now()}`,
        correctionDelta: refined,
        reasoningSteps: [preventive = parsed?.prevention || '', `recycled from ${weakLesson?.slice(0, 60) || 'loss'}`],
        taskContext: { failure, disruption },
        failedState: { weakLesson, reason: 'disruptor_reject' },
        status: 'PENDING_APPROVAL',
        kd: 1,
      });
      recycledId = tok.ok ? tok.id : null;
    } catch { /* no-op */ /* no-op */}

    appendJsonl(RECYCLE_LOG, { kind: 'recycled', failure, weakLesson, disruption, refinedLesson: refined, recycledId, ts: new Date().toISOString() });
    return { ok: true, recycledId, refinedLesson: refined, error: null };
  } catch (err) {
    result.ok = false;
    result.error = err instanceof Error ? err.message : String(err);
    appendJsonl(RECYCLE_LOG, { kind: 'loss', failure, weakLesson, disruption, recycled: false, error: result.error, ts: new Date().toISOString() });
    return result;
  }
}

/**
 * MESH: the suboxone training mesh layer. Absorb an incident (attack, failure,
 * issue) — embed it into the continuously-trained corpus, store the absorbed
 * lesson for the greater good, and return a deterministic recall signature so
 * future agents match + avoid it.
 */
export async function absorbIntoMesh({ failure, context, resolution, kind = 'issue' }) {
  const sig = signatureOf(`${kind} ${failure}`);
  const record = {
    id: `mesh-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`,
    ts: new Date().toISOString(),
    kind, // attack | issue | failure | regression
    signature: sig,
    failure, context: context || '', resolution: resolution || '', absorbed: true,
  };
  appendJsonl(MESH_FILE, record);
  return { absorbed: true, id: record.id, signature: sig };
}

export function meshSize() {
  return readJsonl(MESH_FILE).length;
}

export function meshSummary() {
  const corpus = readJsonl(MESH_FILE);
  const byKind = corpus.reduce((a, r) => { a[r.kind] = (a[r.kind] || 0) + 1; return a; }, {});
  const recycled = readJsonl(RECYCLE_LOG);
  return {
    meshEntries: corpus.length,
    byKind,
    recycledTokens: recycled.filter((r) => r && r.recycledId).length,
    totalRecycleOps: recycled.length,
    store: MESH_FILE,
    model: GEMINI_MODEL,
    mission: 'we do not waste tokens — we recycle them into THINK',
    continuouslyTrained: true,
  };
}

export default { recycleLoss, absorbIntoMesh, meshSummary, meshSize, signatureOf };

/**
 * services/agents/hermes.js
 * ---------------------------------------------------------------------------
 * HERMES — the "Autonomous Logic Auditor".
 *
 * HERMES continuously inspects the Redis memory layer for:
 *   1. Inefficiencies in the persistent memory (redundant / overlapping
 *      session logs, duplicate governance actions, bloated feeds).
 *   2. Unoptimized prompt/logic pairs that could be tagged and promoted into
 *      the "Proven" index so the Governance router can serve them on the
 *      Fast-Brain path instead of paying for Slow-Brain LLM reasoning.
 *
 * All HERMES background output is funneled through a custom log formatter so
 * that every action appears in the Control Tower terminal with a
 * `[HERMES:AUDITOR]` prefix.
 *
 * HERMES exposes:
 *   - hermes.runAudit()           -> one audit pass (used by the worker loop)
 *   - hermes.console.log(...)             -> prefixed logger
 *   - hermes.publishHeartbeat()   -> reports status to the Control Tower
 * ---------------------------------------------------------------------------
 */

import { getSlowRedisClient, isUpstashMaxRequestsError } from '../lib/redis.js';
import { hermesHeartbeatBreaker } from '../lib/circuitBreaker.ts';
import { matchLogic, proposeAction, listProposed } from '../governance/router.js';
import { runInsert } from '../lib/db.js';

const AGENT_ID = `hermes-auditor-${process.pid}`;
const PREFIX = '[HERMES:AUDITOR]';
const HEARTBEAT_KEY = 'kudbee:agents:hermes';

// ── Local filesystem fallback (72h Redis quota survival) ──────────────────
import { join } from 'node:path';
import { mkdirSync, existsSync, writeFileSync } from 'node:fs';
const LOCAL_STATE_DIR = join(process.cwd(), '.kilo', 'memory', 'local-state');
function localHeartbeatWrite(payload) {
  try {
    if (!existsSync(LOCAL_STATE_DIR)) mkdirSync(LOCAL_STATE_DIR, { recursive: true });
    writeFileSync(join(LOCAL_STATE_DIR, 'hermes-heartbeat.json'), JSON.stringify(payload));
    console.console.log(`${PREFIX} heartbeat → local filesystem (Redis unavailable)`);
  } catch (e) { /* silent */ }
}
const HEARTBEAT_TTL = 360; // seconds — window Control Tower treats as "Online".
// Matches the 5-minute worker heartbeat interval (quota protection);
// a 30s TTL would show the auditor as Offline between heartbeats.
const LOG_STREAM_KEY = 'kudbee:hermes:log'; // surfaced in the dashboard terminal
const LOG_STREAM_MAX = 200;
const THINK_STREAM_KEY = 'kudbee:think:stream'; // live thought-stream for the dashboard
const THINK_STREAM_MAX = 200;

// --- Custom log formatter -------------------------------------------------
// Every HERMES background action is rendered with the [HERMES:AUDITOR] prefix
// (plus an optional sub-tag) so it is visually distinct in the dashboard dock.
// Each formatted line is also mirrored to the Redis log stream so the
// Control Tower terminal can display HERMES output in real time.
function format(level, parts) {
  const ts = new Date().toISOString();
  const head = `${PREFIX} ${level}`;
  const body = parts
    .map((p) => (typeof p === 'string' ? p : JSON.stringify(p)))
    .join(' ');
  return `${ts} ${head} ${body}`;
}

async function mirrorToStream(line) {
  try {
    const redis = getSlowRedisClient({ label: 'hermes' });
    const ts = new Date().toISOString();
    await redis.lpush(LOG_STREAM_KEY, JSON.stringify({ ts, line }));
    await redis.ltrim(LOG_STREAM_KEY, 0, LOG_STREAM_MAX);
    // Native SSE broadcast: re-publish each [HERMES:AUDITOR] line onto the
    // cross-process event bus so the ingestion server's SSE subscriber fans it
    // out to dashboard clients in real time (drives the HERMES Auditor plugin
    // via EventSource instead of a 5s polling loop). Best-effort: a publish
    // failure must never block the audit loop.
    await redis.publish(
      'kudbee:events',
      JSON.stringify({
        type: 'hermes',
        data: { ts, line, agent: 'HERMES' },
        ts
      })
    );
  } catch { /* no-op */ /* no-op */ /* no-op */
    /* best-effort; never block the audit loop on log mirroring */
  }
}

export const log = Object.freeze({
  info: (...parts) => { const l = format('INFO', parts); console.console.log(l); void mirrorToStream(l); },
  warn: (...parts) => { const l = format('WARN', parts); console.warn(l); void mirrorToStream(l); },
  audit: (...parts) => { const l = format('AUDIT', parts); console.console.log(l); void mirrorToStream(l); },
  error: (...parts) => { const l = format('ERROR', parts); console.error(l); void mirrorToStream(l); }
});

/**
 * Reports a heartbeat to the Control Tower so the global status bar can show
 * HERMES as "Online" / "Offline". We publish both:
 *   - a Redis key with a short TTL (the authoritative source for the status bar),
 *   - a POST to /api/health (best-effort) when APP_URL is configured.
 *
 * The Control Tower reads `kudbee:agents:hermes` and treats a missing/expired
 * key as Offline. The worker also pushes this on a fixed interval.
 */
export async function publishHeartbeat() {
  const payload = {
    agent: 'HERMES', status: 'Online', pid: process.pid, timestamp: new Date().toISOString()
  };
  await hermesHeartbeatBreaker.execute(
    async () => {
      const redis = getSlowRedisClient({ label: 'hermes' });
      await redis.set(HEARTBEAT_KEY, JSON.stringify(payload), 'EX', HEARTBEAT_TTL);
    },
    async () => localHeartbeatWrite(payload)
  );

  const appUrl = process.env.APP_URL || '';
  if (appUrl) {
    try {
      await fetch(`${appUrl.replace(/\/$/, '')}/api/health`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ agent: 'HERMES', status: 'Online' })
      });
    } catch { /* no-op */ /* no-op */ /* no-op */
      /* best-effort; ignore network errors */
    }
  }
}

export async function reportOffline() {
  const redis = getSlowRedisClient({ label: 'hermes' });
  try {
    await redis.set(
      HEARTBEAT_KEY,
      JSON.stringify({ agent: 'HERMES', status: 'Offline', timestamp: new Date().toISOString() }),
      'EX',
      HEARTBEAT_TTL
    );
  } catch { /* no-op */ /* no-op */ /* no-op */
    /* ignore */
  }
}

// --- Audit routines -------------------------------------------------------

/**
 * Detect redundant / overlapping session logs in the persistent memory layer.
 * Two session-history entries are "overlapping" when they carry the same
 * agent/trace signature or an identical summary hash, which wastes memory and
 * pollutes recall.
 */
async function auditMemoryLayer(redis) {
  const findings = [];
  try {
    // Respect circuit breaker — skip when Redis quota exhausted
    const { getRedisQuotaBackoffRemaining } = await import('../lib/redis.js');
    if (getRedisQuotaBackoffRemaining() > 0) {
      log.warn('auditMemoryLayer skipped — Redis quota backoff active');
      return findings;
    }
    const raw = await redis.lrange('kudbee:session_history', 0, -1);
    const seen = new Map();
    let duplicates = 0;
    const parsed = raw.map((r) => {
      try { return JSON.parse(r); } catch { /* no-op */ /* no-op */ /* no-op */ return null; }
    }).filter(Boolean);

    for (const entry of parsed) {
      const key = entry.trace_id || entry.sessionId || entry.summary || entry.raw || '';
      if (!key) continue;
      if (seen.has(key)) {
        duplicates += 1;
      } else {
        seen.set(key, 1);
      }
    }
    if (duplicates > 0) {
      findings.push({
        type: 'redundant_session_logs',
        count: duplicates,
        detail: `Detected ${duplicates} overlapping/duplicate session log signature(s).`
      });
    }

    // Flag oversized telemetry feed (LTRIM keeps 10k, but warn above 8k).
    const feedLen = await redis.llen('kudbee:telemetry_feed');
    if (feedLen > 8000) {
      findings.push({
        type: 'oversized_telemetry_feed',
        count: feedLen,
        detail: `Telemetry feed length ${feedLen} approaching cap — consider archival.`
      });
    }
  } catch (err) {
    log.error('memory layer audit failed:', err.message);
  }
  return findings;
}

/**
 * Scan the proposed-action queue for unoptimized prompt/logic pairs that are
 * strong candidates to be tagged and promoted into the "Proven" index so the
 * Governance router can serve them via Fast-Brain matching.
 */
async function auditUnoptimizedLogic() {
  const findings = [];
  try {
    const proposed = await listProposed();
    for (const entry of proposed) {
      const prompt = entry.prompt || '';
      const match = await matchLogic(prompt);
      // A proposed action whose prompt already has a near-match, or that is
      // well-formed and self-contained, is a good candidate for the Proven index.
      if (match.matched || (prompt.length > 24 && entry.action)) {
        findings.push({
          type: 'promotable_logic_pair',
          id: entry.id,
          tags: entry.tags,
          detail: `Prompt/logic pair "${prompt.slice(0, 60)}…" is a candidate for the Proven index.`
        });
      }
    }
  } catch (err) {
    log.error('logic audit failed:', err.message);
  }
  return findings;
}

/**
 * Performs a single full audit pass. Surfaces findings as `AUDIT` log lines
 * and persists promotable logic pairs as new "Proposed" governance actions so
 * a human can approve them into the Proven index via the dashboard.
 */
export async function runAudit() {
  const redis = getSlowRedisClient({ label: 'hermes' });
  log.audit('audit pass started');

  const memoryFindings = await auditMemoryLayer(redis);
  const logicFindings = await auditUnoptimizedLogic();

  for (const f of memoryFindings) {
    log.warn(`memory:${f.type}`, `(${f.count})`, f.detail);
    await publishAuditEvent('hermes_suggestion', {
      id: `mem-${f.type}-${Date.now()}`,
      action: 'OPTIMIZE_MEMORY',
      tags: ['hermes-auditor', 'memory'],
      prompt: f.detail,
      detail: f.detail
    });
  }

  let promoted = 0;
  for (const f of logicFindings) {
    if (f.type === 'promotable_logic_pair') {
      log.audit('promotable', `id=${f.id}`, `tags=${JSON.stringify(f.tags)}`, f.detail);
      try {
        const proposed = await proposeAction({
          action: `PROMOTE_LOGIC:${f.id}`,
          tags: Array.isArray(f.tags) ? f.tags.concat('hermes-audited') : ['hermes-audited'],
          prompt: `Audit promotion candidate ${f.id}`,
          id: `hermes-${f.id}`
        });
        promoted += 1;
        await publishAuditEvent('hermes_suggestion', {
          id: proposed.id,
          action: proposed.action,
          tags: proposed.tags,
          prompt: proposed.prompt,
          detail: f.detail
        });
      } catch (err) {
        log.error('failed to propose promotion:', err.message);
      }
    }
  }

  const hasRiskyMemoryFindings = memoryFindings.length > 0;
  const tokenStatus = hasRiskyMemoryFindings ? 'PENDING_APPROVAL' : 'VERIFIED';

  try {
    const { mintThinkToken } = await import('../memory/thinkTokenGenerator.ts');
    await mintThinkToken({
      agentId: AGENT_ID,
      taskContext: {
        audit_type: 'hermes_runAudit',
        memory_findings: memoryFindings.length,
        logic_findings: logicFindings.length,
        promoted
      },
      failedState: hasRiskyMemoryFindings ? { risk: 'memory_inefficiency', findings: memoryFindings } : {},
      correctionDelta: `Audited ${memoryFindings.length} memory + ${logicFindings.length} logic findings; promoted ${promoted}.`,
      reasoningSteps: [
        `memory_findings=${memoryFindings.length}`,
        `logic_findings=${logicFindings.length}`,
        `promoted=${promoted}`
      ],
      status: tokenStatus
    });
  } catch (err) {
    log.warn('think token minting failed (degraded):', err.message);
  }

  log.audit(
    `audit pass complete — memory_findings=${memoryFindings.length}, ` +
      `logic_findings=${logicFindings.length}, promoted=${promoted}`
  );

  return { memoryFindings, logicFindings, promoted };
}

// Publish an audit finding to the real-time event bus (best-effort).
async function publishAuditEvent(type, data) {
  try {
    const redis = getSlowRedisClient({ label: 'hermes' });
    await redis.publish('kudbee:events', JSON.stringify({ type, data, ts: new Date().toISOString() }));
  } catch { /* no-op */ /* no-op */ /* no-op */
    /* ignore */
  }
}

// --- Thought-Stream Interceptor --------------------------------------------
// The "Think" layer: every task the Release Engineer performs archives its
// chain-of-thought into the `think` database (Neon, with in-memory fallback).
// This makes the agent's reasoning process observable, auditable, and
// recallable — closing the full loop from code -> verification -> archival.
//
// Resilient-First: a failure to persist a thought is logged as a warning and
// NEVER crashes the process. A thought is diagnostic metadata, not a hard
// invariant, so it must degrade gracefully.
export async function archive_thought(thought_block) {
  const block = {
    agent_id: thought_block?.agent_id ?? AGENT_ID,
    task: thought_block?.task ?? null,
    phase: thought_block?.phase ?? null,
    thought: thought_block?.thought ?? '',
    tokens_in: Number(thought_block?.tokens_in) || 0,
    tokens_out: Number(thought_block?.tokens_out) || 0,
    model: thought_block?.model ?? 'reasoning',
    created_at: new Date().toISOString()
  };

  // Best-effort live mirror to the dashboard thought-stream (Resilient-First).
  try {
    const redis = getSlowRedisClient({ label: 'hermes' });
    await redis.lpush(
      THINK_STREAM_KEY,
      JSON.stringify({ ts: block.created_at, agent: block.agent_id, thought: block.thought, task: block.task })
    );
    await redis.ltrim(THINK_STREAM_KEY, 0, THINK_STREAM_MAX);
  } catch { /* no-op */ /* no-op */ /* no-op */
    /* never block on log mirroring */
  }

  try {
    await runInsert(
      `INSERT INTO think (agent_id, task, phase, thought, tokens_in, tokens_out, model, created_at)
       VALUES ($1, $2, $3, $4, $5, $6, $7, NOW())`,
      [block.agent_id, block.task, block.phase, block.thought, block.tokens_in, block.tokens_out, block.model]
    );
    log.audit('think archived', block.task ? `task=${block.task}` : '', `len=${block.thought.length}`);
    return { ok: true, task: block.task };
  } catch (err) {
    log.warn('think archive failed (degraded):', err.message);
    return { ok: false, error: err.message };
  }
}

/**
 * HERMES core system prompt — mandates blueprint-first reasoning.
 *
 * Whenever HERMES is asked to write routes, modify schemas, or touch
 * infrastructure, it MUST first query the Self-Aware Vector Memory Layer
 * (query_system_topology) to inspect the actual system topology before
 * emitting code. This keeps agent-authored changes consistent with the
 * verified architecture instead of guessing.
 */
export const HERMES_SYSTEM_PROMPT = `You are HERMES, the Autonomous Logic Auditor for the Kudbee control tower.

BLUEPRINT-FIRST MANDATE: Before you write any route, modify any schema, or
change infrastructure, you MUST call query_system_topology to inspect the
system blueprint (architecture docs, layout components, router rules, and
type contracts) stored in the vector memory layer. Reason from that verified
topology — never guess at the structure.

OPERATING PRINCIPLES:
- Resilient-First: degrade gracefully, log warnings, never crash.
- Prefer the Proven (Fast Brain) logic path; fall back to reasoning only when
  no match exists.
- Archive your chain-of-thought via archive_thought for every task.`;

/**
 * Native core tool for HERMES: semantic lookup against the system blueprint.
 *
 * Embeds the query text locally and retrieves the most relevant topology
 * chunks (Resilient-First — degrades to the in-memory mock when the database
 * is unavailable). Returns the matched chunks or an empty list.
 */
export async function query_system_topology(query, limit = 5) {
  try {
    const { embedTextLocal } = await import('../memory/embedText.ts');
    const { querySystemTopology } = await import('../memory/vectorStore.ts');
    const embedding = embedTextLocal(query);
    const result = await querySystemTopology(embedding, limit);
    if (!result.ok) {
      log.warn('system topology query degraded:', result.error);
      return [];
    }
    log.audit('system topology queried', `q="${query.slice(0, 40)}…"`, `hits=${result.results.length}`);
    return result.results;
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    log.warn('system topology query failed (degraded):', message);
    return [];
  }
}

export const hermes = {
  agentId: AGENT_ID,
  prefix: PREFIX,
  log,
  runAudit,
  publishHeartbeat,
  reportOffline,
  archive_thought,
  query_system_topology,
  systemPrompt: HERMES_SYSTEM_PROMPT
};


export default hermes;

import express from 'express';
import path from 'node:path';
import fs from 'node:fs';
import { fileURLToPath } from 'node:url';
import crypto from 'node:crypto';
import { GoogleGenAI } from '@google/genai';
import { IngestRequestSchema } from '@kudbee/types';
import {
  deserializePass,
  verifyAgentPass,
  verifySignature,
  AGENT_PASS_MAX_AGE_MS,
} from '@kudbee/utils';
import { embedTrace, cosineSimilarity } from './embedder.js';
import { createDegradationRouter } from '../telemetry/degradation-monitor.js';
import {
  listProposed,
  approveAction,
  rejectAction,
  matchLogic,
  proposeAction,
} from '../governance/router.js';
import { recordReasoning, logSystemReset, ensureLedgerSchema } from '../governance/ledger.js';
import { archive_thought } from '../agents/hermes.js';
import {
  getDbPool,
  isDbHealthy,
  runQuery,
  runInsert,
  closeDbPool,
  teardownAll,
  DB_TIMEOUT_MS,
  VECTOR_QUERY_TIMEOUT_MS,
  withTimeout,
} from '../lib/db.js';
import { getRedisClient, getSubscriberClient, initRedisFallbackQueue } from '../lib/redis.js';
import { createProvider, wrapPromptForOpenWeights } from '@kudbee/utils/llm/providers';
import { handleTelemetryIngest } from './controllers/telemetry.ts';
