// Live CI status from GitHub Actions (public API, no token needed) with a
// 60s cache. Falls back to the last POSTed report when GitHub is unreachable.
app.get('/api/ci/status', async (_req, res) => {
  const now = Date.now();
  if (_ciFetchCache.data && now - _ciFetchCache.at < CI_CACHE_MS) {
    return res.json(_ciFetchCache.data);
  }
  try {
    const gh = await fetch('https://api.github.com/repos/KudbeeZero/Kudbee-fuel-gage/actions/runs?branch=main&per_page=1', {
      headers: { 'Accept': 'application/vnd.github+json', 'User-Agent': 'kudbee-control-tower' },
      signal: AbortSignal.timeout(8000),
    });
    const body = await gh.json();
    const run = body.workflow_runs?.[0];
    if (run) {
      const data = {
        status: run.status === 'completed' ? (run.conclusion === 'success' ? 'GREEN' : run.conclusion === 'failure' ? 'FAIL' : 'WARN') : 'RUNNING',
        lastRun: run.created_at,
        runId: run.id,
        headSha: run.head_sha?.slice(0, 7) ?? null,
        workflow: run.name ?? run.workflow_name ?? null,
        source: 'github-actions',
      };
      _ciFetchCache = { at: now, data };
      return res.json(data);
    }
  } catch { /* no-op */ /* no-op */ /* no-op */
    /* GitHub unreachable — fall through to cached report */
  }
  res.json(_ciResults);
});

// --- CI health endpoint (aggregated health for CIHealthPanel) ----------------
// Returns overall health, stats, and recent failures derived from /api/ci/status
// and the internal _ciResults cache.
app.get('/api/ci/health', async (_req, res) => {
  const now = Date.now();
  const ciStatus = _ciFetchCache.data || _ciResults;
  const isGreen = ciStatus?.status === 'GREEN';
  const isRunning = ciStatus?.status === 'RUNNING';
  const overall = isRunning ? 'DEGRADED' : isGreen ? 'HEALTHY' : 'UNSTABLE';
  const total = _ciResults.results?.length ?? 0;
  const passed = _ciResults.results?.filter((r) => r.pass).length ?? 0;
  const failed = total - passed;
  const passRate = total > 0 ? Math.round((passed / total) * 100) : 0;
  const recentFailures = (_ciResults.results ?? [])
    .filter((r) => !r.pass)
    .slice(-5)
    .map((r) => ({
      name: r.name ?? 'unknown',
      branch: r.branch ?? 'main',
      event: r.event ?? 'push',
      url: r.url ?? '',
    }));
  return res.json({
    timestamp: new Date().toISOString(),
    overall,
    latestRun: ciStatus
      ? { name: ciStatus.workflow ?? 'kudbee-ci', conclusion: ciStatus.status, branch: 'main', event: 'push' }
      : null,
    stats: { total, passed, failed, passRate },
    recentFailures,
    source: ciStatus?.source ?? 'internal',
  });
});

