}

const GEMINI_API_KEY = process.env.GEMINI_API_KEY;
let aiClient = null;
let cachedContent = null;

function getGeminiClient() {
  if (!aiClient) {
    if (!GEMINI_API_KEY) {
      console.warn('[Gemini] GEMINI_API_KEY not set — triage disabled');
      return null;
    }
    aiClient = new GoogleGenAI({ apiKey: GEMINI_API_KEY });
  }
  return aiClient;
}

const TRIAGE_SYSTEM_PROMPT = `You are a telemetry triage system. Respond with ONLY one word: "critical" or "ignore".

Rules:
- "critical" if: status is not 'OK', or cost > 0.05, or tokens_in > 1000
- "ignore" if: status is 'OK', cost <= 0.05, tokens_in <= 1000
- When in doubt, respond "ignore"`;

async function getOrCreateCachedContent() {
  if (cachedContent) return cachedContent;
  const client = getGeminiClient();
  if (!client) return null;
  try {
    cachedContent = await client.caches.create({
      model: 'models/gemini-1.5-flash',
      config: {
        contents: [{ role: 'user', parts: [{ text: TRIAGE_SYSTEM_PROMPT }] }],
        displayName: 'kudbee-telemetry-triage',
        ttl: '86400s',
      },
    });
    console.console.log('[Gemini] Context cache created:', cachedContent.name);
    return cachedContent;
  } catch (err) {
    console.warn('[Gemini] Failed to create cached content:', err.message);
    return null;
  }
}

async function triageWithGemini(event) {
  const client = getGeminiClient();
  if (!client) return true;
  const cached = await getOrCreateCachedContent();
  try {
    const prompt = `Classify this telemetry event:\n${JSON.stringify(event, null, 2)}`;
    const response = await client.models.generateContent({
      model: 'models/gemini-1.5-flash',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        ...(cached ? { cachedContent: cached.name } : {}),
        temperature: 0,
        maxOutputTokens: 10,
      },
    });
    const text = response.text || '';
    return text.trim().toLowerCase().includes('critical');
  } catch (err) {
    console.warn('[Gemini] Triage failed, defaulting to persist:', err.message);
    return true;
  }
}

function quarantineViolation(payload, violationReason) {
  publishEvent('triage', {
    payload,
    violation_reason: violationReason,
    timestamp: new Date().toISOString(),
  });
  return runInsert(
    `INSERT INTO security_violations (payload, violation_reason, timestamp)
     VALUES ($1, $2, NOW())`,
    [JSON.stringify(payload ?? null), String(violationReason)]
  );
}

function safeParseJson(value) {
  if (typeof value !== 'string') return value;
  try {
    return JSON.parse(value);
  } catch { /* no-op */ /* no-op */ /* no-op */
    return value;
  }
}

function reverseTokenHash(hash) {
  const hex = String(hash || '').replace(/^0x/i, '');
  if (hex.length % 2 !== 0 || hex.length === 0) return null;
  try {
    return Buffer.from(hex, 'hex').toString('utf8');
  } catch { /* no-op */ /* no-op */ /* no-op */
    return null;
  }
}

function computeTokenHash(row) {
  const key = String(row.id || row.original_trace_id || '');
  return `0x${crypto.createHash('sha256').update(key).digest('hex').slice(0, 16)}`;
}

function storeVector({ traceId, thoughtSummary, reasoning, model, vector, agentId = null }) {
  return runInsert(
    `INSERT INTO telemetry_vectors (trace_id, thought_summary, reasoning, model, vector, timestamp)
     VALUES ($1, $2, $3, $4, $5, NOW())`,
    [
      String(traceId),
      String(thoughtSummary || ''),
      String(reasoning || ''),
      String(model || 'unknown'),
      JSON.stringify(vector),
    ]
  ).then((res) => {
    // Mirror into user_memories (the semantic long-term store, subject to TTL).
    return runInsert(
      `INSERT INTO user_memories (agent_id, thought_summary, reasoning, model, embedding, created_at)
       VALUES ($1, $2, $3, $4, $5, NOW())`,
      [
        agentId ? String(agentId) : null,
        String(thoughtSummary || ''),
        String(reasoning || ''),
        String(model || 'unknown'),
        JSON.stringify(vector),
      ]
    ).catch(() => res);
  });
}

async function recallMemories(query, limit = 3) {
  const queryVec = embedTrace(query, query, 'query');
  const rows = await runQuery(`SELECT * FROM telemetry_vectors ORDER BY timestamp DESC LIMIT 200`);
  const scored = rows
    .map((row) => {
      const vec = safeParseJson(row.vector);
      const similarity = Array.isArray(vec) ? cosineSimilarity(queryVec, vec) : 0;
      return {
        trace_id: row.trace_id,
        thought_summary: row.thought_summary,
        reasoning: row.reasoning,
        model: row.model,
        similarity,
      };
    })
    .filter((r) => r.similarity > 0)
    .sort((a, b) => b.similarity - a.similarity)
    .slice(0, limit);
  return scored;
}

/**
 * Recall the last N persisted user memories (semantic long-term store).
 * Distinct from `recallMemories` (vector search): this returns raw stored
 * memories in reverse-chronological order, capped at `limit`.
 */
async function recallUserMemories(limit = 10) {
  const rows = await runQuery(
    `SELECT id, agent_id, thought_summary, reasoning, model, created_at
     FROM user_memories
     ORDER BY created_at DESC
     LIMIT $1`,
    [Number(limit) || 10]
  );
  return rows
    .map((row) => ({
      id: row.id,
      agent_id: row.agent_id ?? null,
      thought_summary: row.thought_summary || '',
      reasoning: row.reasoning || '',
      model: row.model || 'unknown',
      created_at: row.created_at ?? null,
    }))
    .slice(0, limit);
}

// --- Telemetry ingest firewall: drop low-value / heartbeat events -----------
// Heartbeat and no-op pings must never be persisted; only critical traces land
// in the system of record. This is the deterministic layer that complements the
// Gemini triage model.
const HEARTBEAT_PATTERNS = [
  /^heartbeat$/i,
  /^ping$/i,
  /^health$/i,
  /^keep[-_]?alive$/i,
  /^\/api\/health/i,
  /_ping$/i,
];

function isLowValueEvent({ trace_id, model, tokens_in, tokens_out, cost, status }) {
  const tid = String(trace_id || '').toLowerCase();
  if (HEARTBEAT_PATTERNS.some((re) => re.test(tid))) return true;
  const tokens = (Number(tokens_in) || 0) + (Number(tokens_out) || 0);
  const price = Number(cost) || 0;
  if (tokens === 0 && price === 0 && (status || 'OK') === 'OK' && model === 'heartbeat') {
    return true;
  }
  return false;
}

const METRICS_WINDOW_MS = 60_000;
let _metricsCount = 0;
let _metricsWindowStart = Date.now();

function shouldSample() {
  const rate = parseInt(process.env.SAMPLE_RATE, 10);
  if (!rate || rate <= 0) return true;
  if (rate === 1) return true;
  return Math.random() < 1 / rate;
}

function recordThroughput() {
  const now = Date.now();
  if (now - _metricsWindowStart >= METRICS_WINDOW_MS) {
    if (_metricsCount > 0) {
      const rate = _metricsCount / (METRICS_WINDOW_MS / 1000);
      console.console.log(
        `[Ingest] Throughput: ${_metricsCount} events in ${METRICS_WINDOW_MS / 1000}s (${rate.toFixed(1)}/s) — sample_rate: ${process.env.SAMPLE_RATE || '1 (all)'}`
      );
    }
    _metricsCount = 0;
    _metricsWindowStart = now;
  }
  _metricsCount += 1;
}

const DEDUP_WINDOW_MS = 5_000;
// Serverless-safe dedup: Redis-backed (shared across instances) with an
// in-memory fallback when Redis is unavailable. Replaces the old in-process
// Map, which broke under multi-instance/serverless scaling.
import { createDedupStore } from '../lib/dedupStore.ts';
let _dedupStoreInstance = null;
function getDedupStore() {
  if (!_dedupStoreInstance) {
    _dedupStoreInstance = createDedupStore({ windowMs: DEDUP_WINDOW_MS, redis });
  }
  return _dedupStoreInstance;
}

async function isDuplicateTrace(traceId) {
  const key = String(traceId || '');
  if (!key) return false;
  return getDedupStore().isDuplicate(key);
}

async function clearDedup(traceId) {
  await getDedupStore().clear(String(traceId || ''));
}

app.post('/api/telemetry/ingest', ftwbGuard(), async (req, res) => {
  try {
    // Pre-flight health check: reject ingest when both DB and Redis are down.
    const dbHealthy = isDbHealthy();
    if (!dbHealthy && !redis) {
      return res.status(503).json({
        error: 'Service Unavailable',
        reason: 'Both database and cache are unreachable — pipeline degraded',
        db_healthy: false,
        redis: false,
      });
    }

    const agentId = authenticateAgentPass(req.header('X-Agent-Pass'));
    const {
      trace_id,
      model,
      tokens_in,
      tokens_out,
      cost,
      status,
      provider,
      project_name,
      thought_summary,
      reasoning,
    } = req.body || {};
    const effectiveStatus = agentId ? status || 'authenticated_bypass' : status || 'OK';

    // Firewall: drop low-value / heartbeat events before any persistence.
    if (
      isLowValueEvent({ trace_id, model, tokens_in, tokens_out, cost, status: effectiveStatus })
    ) {
      return res.status(200).json({
        success: true,
        id: null,
        agent: agentId || undefined,
        bypass: !!agentId,
        recalled_context: [],
        message: 'Event filtered at ingest firewall (low-value/heartbeat) — not persisted',
      });
    }

    recordThroughput();

    if (!agentId && !shouldSample()) {
      return res.status(200).json({
        success: true,
        id: null,
        agent: undefined,
        bypass: false,
        recalled_context: [],
        message: 'Event sampled (not persisted per SAMPLE_RATE configuration)',
      });
    }

      if (!agentId && await isDuplicateTrace(trace_id)) {
      return res.status(200).json({
        success: true,
        id: null,
        agent: undefined,
        bypass: false,
        recalled_context: [],
        message: 'Duplicate trace_id within dedup window — skipped',
      });
    }

    if (!agentId) {
      const parsed = IngestRequestSchema.safeParse(req.body);
      if (!parsed.success) {
        const reason = parsed.error.issues
          .map((i) => `${i.path.join('.') || '(root)'}: ${i.message}`)
          .join('; ');
        await quarantineViolation(req.body, reason);
        return res
          .status(422)
          .json({ error: 'Firewall: invalid telemetry contract', issues: parsed.error.issues });
      }
    }

    const isHeartbeatPing =
      Number(tokens_in) <= 1 && Number(tokens_out) <= 1 && effectiveStatus === 'OK';
    const isHighValueModel = HIGH_VALUE_MODELS.has(String(model || '').toLowerCase());
    const shouldSave = !isHeartbeatPing && (effectiveStatus !== 'OK' || isHighValueModel);

    if (!shouldSave) {
      return res.status(200).json({
        success: true,
        id: null,
        agent: agentId || undefined,
        bypass: !!agentId,
        recalled_context: [],
        message: `Event filtered at budget firewall (low-value heartbeat) — not persisted`,
      });
    }

    const effectiveThought = agentId
      ? thought_summary || ''
      : truncatePayload(thought_summary || '', MAX_REASONING_LENGTH);
    const effectiveReasoning = agentId
      ? reasoning || ''
      : truncatePayload(reasoning || '', MAX_REASONING_LENGTH);

    const shouldPersist = await triageWithGemini({
      trace_id,
      model,
      tokens_in,
      tokens_out,
      cost,
      status: effectiveStatus,
      provider,
      project_name,
    });

    if (!shouldPersist) {
      return res.status(200).json({
        success: true,
        id: null,
        agent: agentId || undefined,
        bypass: !!agentId,
        recalled_context: [],
        message: 'Event filtered by Gemini triage (low-value)',
      });
    }

    const recall = await recallMemories(
      [effectiveThought, effectiveReasoning, model].filter(Boolean).join(' '),
      3
    ).catch((e) => {
      console.error('[Memory] Recall failed, continuing without context:', e.message);
      return [];
    });

    const result = await runInsert(
      `INSERT INTO telemetry_traces (trace_id, model, tokens_in, tokens_out, cost, status, provider, project_name, timestamp, input_tokens, output_tokens)
       VALUES ($1, $2, $3, $4, $5, $6, $7, $8, NOW(), $3, $4)
       ON CONFLICT (trace_id) DO UPDATE SET
         tokens_in = EXCLUDED.tokens_in,
         tokens_out = EXCLUDED.tokens_out,
         cost = EXCLUDED.cost,
         status = EXCLUDED.status,
         timestamp = NOW()`,
      [
        String(trace_id ?? (agentId ? `agent-${agentId}` : 'unknown')),
        String(model || 'unknown'),
        Number(tokens_in) || 0,
        Number(tokens_out) || 0,
        Number(cost) || 0,
        String(effectiveStatus),
        String(provider || 'unknown'),
        String(project_name || 'kilo-fuel-gauge'),
      ]
    );

    // Vector store: only embed events with meaningful reasoning context.
    // Low-token heartbeat-like events skip embedding to conserve DB writes.
    const tokens = (Number(tokens_in) || 0) + (Number(tokens_out) || 0);
    const shouldEmbed = agentId || tokens > 10 || effectiveStatus !== 'OK' || isHighValueModel;
    if (shouldEmbed) {
      const vector = embedTrace(effectiveReasoning, effectiveThought, model || 'unknown');
      storeVector({
        traceId: trace_id ?? (agentId ? `agent-${agentId}` : 'unknown'),
        thoughtSummary: effectiveThought,
        reasoning: effectiveReasoning,
        model: model || 'unknown',
        vector,
        agentId,
      }).catch((e) => console.error('[Memory] Vector store failed (observability):', e.message));
    }

    if (agentId) {
      console.console.log(`[Identity] Fast-path bypass granted for agent ${agentId} (trace ${result.id})`);
    }

    const responsePayload = {
      success: true,
      id: result.id,
      agent: agentId || undefined,
      bypass: !!agentId,
      recalled_context: recall,
      message: agentId
        ? 'Telemetry trace ingested via authenticated agent fast-path'
        : 'Telemetry trace ingested successfully',
    };

    // Real egressed signal — built unconditionally so the SSE broadcast
    // below always has valid data, then mirrored to the Redis feed (best-effort
    // when a cache is configured).
    const feedEntry = {
      trace_id: trace_id ?? (agentId ? `agent-${agentId}` : 'unknown'),
      model: model || 'unknown',
      tokens_in: Number(tokens_in) || 0,
      tokens_out: Number(tokens_out) || 0,
      cost: Number(cost) || 0,
      status: effectiveStatus,
      provider: provider || 'unknown',
      project_name: project_name || 'kilo-fuel-gauge',
      timestamp: new Date().toISOString(),
    };

    if (redis) {
      redis
        .lpush('kudbee:telemetry_feed', JSON.stringify(feedEntry))
        .then(() => redis.ltrim('kudbee:telemetry_feed', 0, 9999))
        .catch(async (e) => {
          console.error('[Redis] Telemetry feed push failed:', e.message);
          const { getOrCreateInMemoryQueue } = await import('../lib/inMemoryQueue.ts');
          const fallbackQueue = getOrCreateInMemoryQueue();
          fallbackQueue.enqueue({
            queue: 'kudbee:telemetry_feed',
            data: feedEntry,
            source: 'ingestion-telemetry-feed',
          });
        });
    } else {
      const { getOrCreateInMemoryQueue } = await import('../lib/inMemoryQueue.ts');
      const fallbackQueue = getOrCreateInMemoryQueue();
      fallbackQueue.enqueue({
        queue: 'kudbee:telemetry_feed',
        data: feedEntry,
        source: 'ingestion-telemetry-feed',
      });
    }

    // Native SSE broadcast of the real egressed signal so the Edge Sentinel
    // plugin can pulse/shift on live ingress events (replaces polling).
    publishEvent('telemetry', {
      trace_id: feedEntry.trace_id,
      model: feedEntry.model,
      tokens_in: feedEntry.tokens_in,
      tokens_out: feedEntry.tokens_out,
      cost: feedEntry.cost,
      status: feedEntry.status,
      latency_ms: 0,
      agent: agentId || null,
      ts: feedEntry.timestamp,
    });

    publishEvent('memory.ingested', {
      trace_id: feedEntry.trace_id,
      agentId: agentId || null,
      category: effectiveStatus === 'OK' ? 'FACT' : 'OBSERVATION',
      importance: isHighValueModel ? 0.9 : 0.5,
      content: (effectiveThought || effectiveReasoning || feedEntry.trace_id).slice(0, 80),
      ts: feedEntry.timestamp,
    });

    return res.status(201).json(responsePayload);
  } catch (err) {
    console.error('[Ingest] Error:', err.message);
    return res.status(500).json({ error: 'Internal server error', details: err.message });
  }
});

// --- Batch telemetry ingest: accepts an array of events in a single request ---
app.post('/api/telemetry/ingest/batch', async (req, res) => {
  try {
    const events = req.body?.events;
    if (!Array.isArray(events) || events.length === 0) {
      return res.status(400).json({ error: 'events array is required' });
    }
    if (events.length > 100) {
      return res.status(400).json({ error: 'batch limited to 100 events' });
    }

    const dbHealthy = isDbHealthy();
    if (!dbHealthy && !redis) {
      return res
        .status(503)
        .json({ error: 'Service Unavailable', reason: 'DB and cache unreachable' });
    }

    const agentId = authenticateAgentPass(req.header('X-Agent-Pass'));
    let persisted = 0;
    let filtered = 0;
    let sampled = 0;
    let deduped = 0;

    for (const event of events) {
      const { trace_id, model, tokens_in, tokens_out, cost, status, provider, project_name } =
        event || {};
      recordThroughput();

      if (
        isLowValueEvent({ trace_id, model, tokens_in, tokens_out, cost, status: status || 'OK' })
      ) {
        filtered++;
        continue;
      }
    if (!agentId && await isDuplicateTrace(trace_id)) {
        deduped++;
        continue;
      }
      if (!agentId && !shouldSample()) {
        sampled++;
        continue;
      }

      const effectiveStatus = agentId ? status || 'authenticated_bypass' : status || 'OK';
      const isHeartbeatPing =
        Number(tokens_in) <= 1 && Number(tokens_out) <= 1 && effectiveStatus === 'OK';
      const isHighValue = HIGH_VALUE_MODELS.has(String(model || '').toLowerCase());
      if (!isHeartbeatPing || isHighValue) {
        await runInsert(
          `INSERT INTO telemetry_traces (trace_id, model, tokens_in, tokens_out, cost, status, provider, project_name, timestamp, input_tokens, output_tokens)
           VALUES ($1, $2, $3, $4, $5, $6, $7, $8, NOW(), $3, $4)
           ON CONFLICT (trace_id) DO UPDATE SET tokens_in = EXCLUDED.tokens_in, tokens_out = EXCLUDED.tokens_out, cost = EXCLUDED.cost, status = EXCLUDED.status, timestamp = NOW()`,
          [
            String(trace_id),
            String(model || 'unknown'),
            Number(tokens_in) || 0,
            Number(tokens_out) || 0,
            Number(cost) || 0,
            String(effectiveStatus),
            String(provider || 'unknown'),
            String(project_name || 'kilo-fuel-gauge'),
          ]
        ).catch(() => {
          filtered++;
        });
        persisted++;
      } else {
        filtered++;
      }
    }

    return res.status(201).json({
      success: true,
      received: events.length,
      persisted,
      filtered,
      sampled,
      deduped,
      message: `Batch processed: ${persisted} persisted, ${filtered} filtered, ${sampled} sampled, ${deduped} deduped`,
    });
  } catch (err) {
    console.error('[Ingest:Batch] Error:', err.message);
    return res.status(500).json({ error: 'Batch ingest failed', details: err.message });
  }
});

// --- Agent Verification / Handshake Endpoint --------------------------------
// Allows existing workers to securely prove their identity before making
// authenticated requests. The agent signs a challenge with its private key;
// the server verifies it against the registered public key in config/agents.json.
app.post('/api/agents/verify', express.json(), (req, res) => {
  try {
    const { agentId, publicKey, challenge, signature } = req.body || {};

    if (!agentId || !publicKey || !challenge || !signature) {
      return res.status(400).json({
        verified: false,
        error: 'Missing required fields: agentId, publicKey, challenge, signature',
      });
    }

    const registryKey = AGENT_REGISTRY.get(agentId);
    if (!registryKey) {
      return res.status(401).json({
        verified: false,
        error: `Agent '${agentId}' is not registered`,
      });
    }

    if (registryKey !== publicKey) {
      return res.status(401).json({
        verified: false,
        error: 'Public key does not match registered key for this agent',
      });
    }

    const isValid = verifySignature(publicKey, challenge, signature);
    if (!isValid) {
      return res.status(401).json({
        verified: false,
        error: 'Invalid signature for challenge',
      });
    }

    return res.status(200).json({
      verified: true,
      agentId,
      serverTime: new Date().toISOString(),
    });
  } catch (err) {
    console.error('[AgentVerify] Error:', err.message);
    return res.status(500).json({ verified: false, error: 'Verification failed' });
  }
});

