// --- GitHub Repository Connector (agent dynamic file reads) -----------------
// Resilient-First: a missing PAT, unreachable GitHub API, or missing file
// degrades to a typed error response — this endpoint never crashes the server.
app.get('/api/system/file', async (req, res) => {
  const repoPath = typeof req.query.path === 'string' ? req.query.path : '';
  if (!repoPath) {
    return res.status(400).json({
      error: 'Missing "path" query parameter. Expected "owner/repo/path/to/file".',
      ok: false,
    });
  }

  try {
    const result = await fetchFile(repoPath);
    if (!result.ok) {
      const status = result.code === 'INVALID_PATH' ? 400 : result.code === 'NOT_FOUND' ? 404 : 503;
      return res.status(status).json({ error: result.error, code: result.code, ok: false });
    }
    return res.status(200).json({
      ok: true,
      path: repoPath,
      cached: result.cached,
      content: result.content,
    });
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    console.warn('[GitHub] /api/system/file degraded:', message);
    return res.status(503).json({ error: `GitHub connector unavailable: ${message}`, ok: false });
  }
});

// SSE connection tracking — prevents subscriber leak from reconnection storms
const MAX_SSE_CONNECTIONS = 5;
let _sseConnections = 0;
let _sseConnectionId = 0;

app.get('/api/sse/stream', async (req, res) => {
  if (_sseConnections >= MAX_SSE_CONNECTIONS) {
    res.writeHead(503, { 'Content-Type': 'text/event-stream' });
    res.write('event: error\ndata: Too many SSE connections\n\n');
    res.end();
    return;
  }
  const cid = ++_sseConnectionId;
  _sseConnections++;
  const channel = String(req.query.channel || 'kudbee:events');
  res.writeHead(200, {
    'Content-Type': 'text/event-stream',
    'Cache-Control': 'no-cache',
    'Connection': 'keep-alive',
    'Access-Control-Allow-Origin': '*',
  });
  res.write(`: connected to ${channel} [conn#${cid}]\n\n`);
  if (!redis) { res.write('event: error\ndata: Redis unavailable\n\n'); res.end(); _sseConnections--; return; }
  const sub = redis.duplicate();
  await sub.subscribe(channel);
  // Heartbeat every 15s to keep connection alive
  const heartbeat = setInterval(() => { try { res.write(': heartbeat\n\n'); } catch { /* no-op */ /* no-op */ /* no-op */} }, 15000);
  req.on('close', () => {
    clearInterval(heartbeat);
    sub.unsubscribe(channel);
    sub.quit();
    _sseConnections--;
  });
  sub.on('message', (_ch, msg) => { try { res.write(`data: ${msg}\n\n`); } catch { /* no-op */ /* no-op */ /* no-op */} });
});

