// --- Real-time telemetry: Server-Sent Events (SSE) -----------------------
// The web server and the HERMES worker are separate processes, so we use a
// Redis pub/sub channel (`kudbee:events`) as the cross-process event bus.
// The server subscribes once and fans every event out to all connected SSE
// clients. `broadcast()` writes to local clients; `publishEvent()` also pushes
// to Redis so the worker (and other server dynos) can emit events too.

const EVENTS_CHANNEL = 'kudbee:events';
const MAX_SSE_CLIENTS = 100;
const sseClients = new Set();

function sseClientCount() {
  return sseClients.size;
}

function broadcast(event) {
  const payload = `event: ${event.type}\ndata: ${JSON.stringify(event.data)}\n\n`;
  const deadClients = [];
  for (const res of sseClients) {
    try {
      res.write(payload);
    } catch { /* no-op */ /* no-op */ /* no-op */
      deadClients.add(res);
    }
  }
  for (const res of deadClients) {
    sseClients.delete(res);
  }
}

function _setupSSEHealth(res, keepAlive) {
  const cleanup = () => {
    clearInterval(keepAlive);
    sseClients.delete(res);
  };
  res.on('close', cleanup);
  res.on('error', (err) => {
    if (err && (err.code === 'ECONNRESET' || err.code === 'EPIPE' || err.code === 'ECONNABORTED')) {
      cleanup();
    }
  });
}

function publishEvent(type, data) {
  // Single delivery path: publish to Redis; the subscriber connection fans
  // out to all local SSE clients. (Calling broadcast() here too would double
  // deliver server-originated events.)
  if (redis) {
    try {
      redis
        .publish(EVENTS_CHANNEL, JSON.stringify({ type, data, ts: new Date().toISOString() }))
        .catch((e) => {
          console.warn('[publishEvent] Redis publish failed:', e.message);
        });
      void publishUnifiedEvent('governance', type, data, EVENTS_CHANNEL);
    } catch { /* no-op */ /* no-op */ /* no-op */
      /* ignore */
    }
  }
}

// Dedicated subscriber connection (ioredis requires subscriber mode).
// Uses getSubscriberClient() which includes retries, offline queueing, and
// TLS settings so the SSE event bus survives transient Redis outages.
if (redis) {
  try {
    const subClient = getSubscriberClient();
    subClient.subscribe(EVENTS_CHANNEL, (err) => {
      if (err) console.error('[SSE] Failed to subscribe to events channel:', err.message);
      else console.console.log('[SSE] Subscribed to', EVENTS_CHANNEL);
    });
    subClient.on('message', (_channel, message) => {
      try {
        const event = JSON.parse(message);
        broadcast(sanitizeEvent(event));
      } catch { /* no-op */ /* no-op */ /* no-op */
        /* ignore malformed */
      }
    });
    subClient.on('error', (err) => console.error('[SSE] Subscriber error:', err.message));
  } catch (err) {
    console.error('[SSE] Subscriber init error:', err.message);
  }
}

// --- SSE Stream Ticket (zero-trust handshake) ---
const STREAM_TICKETS = new Map();
const TICKET_TTL_MS = 30000;
const STREAM_SECRET = process.env.STREAM_SECRET || crypto.randomBytes(32).toString('hex');

if (!process.env.STREAM_SECRET) {
  console.warn(
    '[SSE] STREAM_SECRET not set — using ephemeral in-memory fallback (signatures reset on restart)'
  );
}

app.post('/api/auth/stream-ticket', (req, res) => {
  const ticket = 'sse_ticket_' + crypto.randomUUID();
  STREAM_TICKETS.set(ticket, Date.now() + TICKET_TTL_MS);
  const sig = crypto
    .createHmac('sha256', STREAM_SECRET)
    .update(ticket + ':' + Date.now())
    .digest('hex');
  res.json({ ticket, signature: sig, expiresIn: TICKET_TTL_MS });
});

// --- Admin session verification (replaces the hardcoded client-side
// passkey in apps/web LoginView). Validates against ADMIN_PASS env var
// (falls back to EDGE_AGENT_PASS for existing single-user setups) and
// returns a short-lived HMAC-signed session token. The passkey is NEVER
// shipped in frontend code.
const ADMIN_SESSION_TTL_MS = 12 * 60 * 60 * 1000; // 12h

function adminPass() {
  return process.env.ADMIN_PASS || process.env.EDGE_AGENT_PASS || '';
}

function signAdminSession() {
  const issued = Date.now();
  const token = `admin_${crypto.randomUUID()}`;
  const sig = crypto
    .createHmac('sha256', SESSION_SECRET)
    .update(`${token}:${issued}`)
    .digest('hex');
  return { token, sig, issued, expiresAt: issued + ADMIN_SESSION_TTL_MS };
}

app.post('/api/admin/verify-pass', (req, res) => {
  const expected = adminPass();
  if (!expected) {
    // No admin pass configured — deny rather than fall back to an open door.
    return res.status(503).json({ error: 'ADMIN_PASS not configured on server' });
  }
  const provided = String((req.body && req.body.passkey) || '');
  if (!provided || provided.length > 512) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  // Constant-time comparison to avoid timing side-channels.
  const a = Buffer.from(provided);
  const b = Buffer.from(expected);
  const ok = a.length === b.length && crypto.timingSafeEqual(a, b);
  if (!ok) return res.status(401).json({ error: 'Unauthorized' });
  const session = signAdminSession();
  res.json({ authenticated: true, session });
