// --- Vector Store Sync (chunking + embedding pipeline) ----------------------

function chunkText(text, size = 400) {
  const out = [];
  const t = String(text || '').trim();
  if (!t) return out;
  for (let i = 0; i < t.length; i += size) {
    out.push({ id: `chunk-${out.length}`, text: t.slice(i, i + size), offset: i });
  }
  return out;
}

