          return [key, val];
        }
        await new Promise((r) => setTimeout(r, 500));
      }
      return null;
    },
    lpop,
    lpush,
    rpush,
    llen,
    publish,
    ping,
    on,
    disconnect,
    isRestClient: true,
  };
}

