// ---------------------------------------------------------------------------
// HTTP server (guarded handler)
// ---------------------------------------------------------------------------

const server = createServer(async (req, res) => {
  try {
    // Enterprise CORS: reflect only the local host origin; never `*` on an
    // endpoint that executes commands. Blocks DNS-rebinding / drive-by pages.
    const origin = req.headers.origin;
    const allowedHosts = ["127.0.0.1", "localhost"];
    const host = String(req.headers.host || "").split(":")[0];
    const allowed = (origin ? origin.startsWith("http://127.0.0.1:") || origin.startsWith("http://localhost:") : allowedHosts.includes(host));
    if (allowed) {
      res.setHeader("Access-Control-Allow-Origin", origin || `http://${host}`);
      res.setHeader("Vary", "Origin");
    }
    res.setHeader("Access-Control-Allow-Headers", "Content-Type, X-Agent-Pass");
    res.setHeader("Access-Control-Allow-Methods", "GET, POST, OPTIONS");
    if (req.method === "OPTIONS") { res.writeHead(204); res.end(); return; }

    const url = (req.url || "/").split("?")[0];

    // Gate mutating/executing endpoints behind a shared token. The dashboard
    // derives it from GASTOWN_DASHBOARD_TOKEN (or STREAM_SECRET as fallback),
    // matching how the monorepo terminal-auth gate works. Read roots stay open.
    const DASHBOARD_TOKEN = process.env.GASTOWN_DASHBOARD_TOKEN || process.env.STREAM_SECRET || "";
    const bearerGuard = (wantsToken) => {
      if (!wantsToken) return true;
      if (!DASHBOARD_TOKEN) return false; // fail closed: no token configured => locked
      const t = req.headers["x-agent-pass"];
      return typeof t === "string" && t.length > 0 && t === DASHBOARD_TOKEN;
    };

    // Live state feed (read-only). Open when no token is configured (local),
    // token-gated when DASHBOARD_TOKEN is set.
    if (req.method === "GET" && url === "/api/state") {
      if (!bearerGuard(!!DASHBOARD_TOKEN)) { sendJson(res, 401, { ok: false, error: "unauthorized" }); return; }
      sendJson(res, 200, await getState());
      return;
    }

    // Gas Town feed (bus firewall + phone system)
    if (req.method === "GET" && url === "/api/gastown") {
      sendJson(res, 200, await getGasTownFeed());
      return;
    }

    // Inception Labs live feed (Mercury-2 config + budget + endpoint health)
    if (req.method === "GET" && url === "/api/inception") {
      sendJson(res, 200, await getInceptionFullFeed());
      return;
    }

    // AWS / EC2 / RDS live feed (configured instances + cluster metadata)
    if (req.method === "GET" && url === "/api/aws") {
      sendJson(res, 200, await getAwsFullFeed());
      return;
    }

    // Interactive terminal (bounded body, guarded dispatch, ALWAYS auth-gated)
    if (req.method === "POST" && url === "/api/terminal") {
      if (!bearerGuard(true)) { sendJson(res, 401, { type: "terminal:error", exitCode: 1, output: "Unauthorized: X-Agent-Pass header required." }); return; }
      let raw = "";
      let size = 0;
      let overLimit = false;
      for await (const chunk of req) {
        size += chunk.length;
        if (size > MAX_BODY_BYTES) { overLimit = true; break; }
        raw += chunk;
      }
      if (overLimit) { sendJson(res, 413, { type: "terminal:error", exitCode: 1, output: "Request body too large." }); return; }
      let body = {};
      try { body = raw ? JSON.parse(raw) : {}; } catch { /* no-op */ /* no-op */ sendJson(res, 400, { type: "terminal:error", exitCode: 1, output: "Invalid JSON body." }); return; }
      const cmd = String(body.command || "").trim();
      if (!cmd) { sendJson(res, 400, { type: "terminal:error", exitCode: 1, output: "Command required." }); return; }
      sendJson(res, 200, await runTerminalCommand(cmd));
      return;
    }

    // Live heartbeat (used by load balancers / probes)
    if (req.method === "GET" && url === "/api/health") {
      sendJson(res, 200, { status: "ok", uptime: process.uptime(), ts: new Date().toISOString() });
      return;
    }

    // Serve the self-contained frontend
    const file = decodeURIComponent(url === "/" ? "index.html" : url.slice(1)).replace(/\\/g, "/");
    if (file.includes("..")) { res.writeHead(400); res.end("Bad path"); return; }
    const target = path.join(__dirname, "gastown-dashboard", file);
    const content = await readFile(target);
    const ext = path.extname(target).toLowerCase();
    const mime = ext === ".css" ? "text/css" : ext === ".js" ? "text/javascript" : ext === ".svg" ? "image/svg+xml" : ext === ".woff2" ? "font/woff2" : ext === ".json" ? "application/json" : "text/html";
    res.setHeader("Content-Type", mime);
    res.setHeader("Cache-Control", ext === ".html" ? "no-cache" : "public, max-age=600");
    res.end(content);
  } catch (e) {
    // If we already sent headers, we can't write a body — just close safely.
    if (res.headersSent) { try { res.end(); } catch { /* no-op */ /* no-op */} return; }
    sendJson(res, 500, { ok: false, error: "server_error", message: e instanceof Error ? e.message : String(e) });
  }
});

// ---------------------------------------------------------------------------
// WebSocket live feed
// ---------------------------------------------------------------------------

const wss = new WebSocketServer({ noServer: true });

function sendToSockets(payload) {
  const msg = (() => { try { return JSON.stringify(payload); } catch { /* no-op */ /* no-op */ return null; } })();
  if (!msg) return;
  for (const ws of wss.clients) {
    if (ws.readyState === (typeof ws.OPEN === "number" ? ws.OPEN : 1)) {
      try { ws.send(msg); } catch { /* no-op */ /* no-op */}
    }
  }
}

async function snapState() {
  try { return await getState(); } catch (e) { return { ok: false, error: e?.message || "state failed" }; }
}

wss.on("connection", (ws) => {
  let stopped = false;
  const push = async () => {
    if (stopped) return;
    try {
      sendToSockets(await snapState());
    } catch { /* no-op */ /* no-op */}
  };
  push();
  ws._timer = setInterval(push, POLL_INTERVAL_MS);
  ws.on("close", () => { stopped = true; if (ws._timer) clearInterval(ws._timer); });
  ws.on("error", () => { stopped = true; if (ws._timer) clearInterval(ws._timer); try { ws.close(); } catch { /* no-op */ /* no-op */} });
});

server.on("upgrade", (req, socket, head) => {
  try {
    if (req.url === "/ws") {
      wss.handleUpgrade(req, socket, head, (ws) => wss.emit("connection", ws, req));
    } else {
      socket.destroy();
    }
  } catch { /* no-op */ /* no-op */
    try { socket.destroy(); } catch { /* no-op */ /* no-op */}
  }
});

server.on("clientError", (_err, socket) => {
  try { socket.end("HTTP/1.1 400 Bad Request\r\n\r\n"); } catch { /* no-op */ /* no-op */}
});

// ---------------------------------------------------------------------------
// Startup + graceful shutdown
// ---------------------------------------------------------------------------

server.listen(PORT, "127.0.0.1", () => {
  log.info(`Gas Town Dashboard: http://127.0.0.1:${PORT}`);
});

function shutdown(signal) {
  log.info(`Received ${signal}; shutting down gracefully…`);
  const timer = setTimeout(() => { log.warn("Forced exit after timeout"); process.exit(1); }, 5000);
  timer.unref();
  for (const ws of wss.clients) { try { ws.close(); } catch { /* no-op */ /* no-op */} }
  wss.close(() => {});
  server.close(() => { clearTimeout(timer); process.exit(0); });
}
process.on("SIGINT", () => shutdown("SIGINT"));
process.on("SIGTERM", () => shutdown("SIGTERM"));

/**
 * maintenance.js — system health + safe optimizations in Node.
 *
 * Port of agent/maintain.ps1 to pure Node so the os-agent no longer depends on
 * PowerShell. Health is gathered from Node's os module (always available) with
 * optional richer data (temp size, top processes, GPU) when a shell is present.
 */
import os from "node:os";
import fs from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { AGENT_DIR } from "./config.js";
import { shellCommand } from "./shell.js";
import { spawn } from "node:child_process";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "..");       // os-agent/
// _WORKSPACE intentionally unused placeholder for dev scripts; keep commented to avoid lint warnings
// const _WORKSPACE = path.resolve(ROOT, "..");       // testLM/ (unused placeholder)
const MEMORY_DIR = path.join(AGENT_DIR, "memory");
const MEMORY_FILE = path.join(MEMORY_DIR, "learnings.json");

function bytesToGb(b) { return (b / (1024 * 1024 * 1024)); }
function bytesToMb(b) { return (b / (1024 * 1024)); }

function nowIso() { return new Date().toISOString(); }

async function ensureMemoryFile() {
  try {
    await fs.access(MEMORY_FILE);
  } catch { /* no-op */ /* no-op */
    await fs.mkdir(MEMORY_DIR, { recursive: true });
    await fs.writeFile(MEMORY_FILE, JSON.stringify({ system: {}, health: {}, optimizations: [], learnings: [] }, null, 2), "utf8");
  }
}

async function readMemory() {
  await ensureMemoryFile();
  const raw = await fs.readFile(MEMORY_FILE, "utf8");
  return JSON.parse(raw.replace(/^\uFEFF/, ""));
}

/** Approximate temp-folder size using Node fs recursion (works without PowerShell). */
async function tempDirSizeMB() {
  const temp = process.env.TEMP || process.env.TMP || "/tmp";
  const total = { bytes: 0 };
  async function walk(dir) {
    let entries;
    try { entries = await fs.readdir(dir, { withFileTypes: true }); }
    catch { /* no-op */ /* no-op */ return; }
    for (const e of entries) {
      const full = path.join(dir, e.name);
      try {
        if (e.isDirectory()) await walk(full);
        else if (e.isSymbolicLink()) { /* skip */ }
        else { const s = await fs.stat(full); total.bytes += s.size; }
      } catch { /* no-op */ /* no-op */ /* skip unreadable */ }
    }
  }
  await walk(temp);
  return bytesToMb(total.bytes);
}

/** Recursively remove files under the temp folder (safe, best-effort). */
async function cleanupTemp() {
  const temp = process.env.TEMP || process.env.TMP || "/tmp";
  async function del(dir) {
    let entries;
    try { entries = await fs.readdir(dir, { withFileTypes: true }); }
    catch { /* no-op */ /* no-op */ return; }
    for (const e of entries) {
      const full = path.join(dir, e.name);
      try {
        if (e.isDirectory()) await del(full), await fs.rmdir(full).catch(() => {});
        else await fs.unlink(full).catch(() => {});
      } catch { /* no-op */ /* no-op */ /* best effort */ }
    }
  }
  await del(temp);
}

/** Top processes by working-set size (Windows via PowerShell, else process list). */
async function topProcesses(count = 5) {
  const sh = shellCommand("Get-Process | Sort-Object WorkingSet64 -Descending | Select-Object -First " + count + " | ForEach-Object { \"$($_.Name) ($([math]::Round($_.WorkingSet64 / 1MB, 0)) MB)\" }");
  if (sh) {
    try {
      const p = spawn(sh.exe, sh.args, { stdio: ["ignore", "pipe", "pipe"] });
      let out = "";
      for await (const chunk of p.stdout) out += chunk;
      const lines = out.split(/\r?\n/).map((s) => s.trim()).filter(Boolean);
      return lines.slice(0, count);
    } catch { /* no-op */ /* no-op */ /* fall through */ }
  }
  // No PowerShell: report by CPU count / system info instead.
  return os.cpus().slice(0, count).map((c) => `${c.model.trim()} ${c.speed} MHz`);
}

/** GPU names when PowerShell is present (Win32_VideoController); else empty. */
async function gpuNames() {
  const sh = shellCommand("Get-CimInstance Win32_VideoController | ForEach-Object { $_.Name }");
  if (!sh) return [];
  try {
    const p = spawn(sh.exe, sh.args, { stdio: ["ignore", "pipe", "pipe"] });
    let out = "";
    for await (const chunk of p.stdout) out += chunk;
    return out.split(/\r?\n/).map((s) => s.trim()).filter(Boolean);
  } catch { /* no-op */ /* no-op */ return []; }
}

/** Gather system health. Returns { memPct, diskFreeGb, tempMb, gpus, topProcs }. */
export async function collectHealth() {
  const totalBytes = os.totalmem();
  const freeBytes = os.freemem();
  const usedPct = totalBytes > 0 ? Math.round(((totalBytes - freeBytes) / totalBytes) * 100) : 0;

  const diskFreeGb = Object.entries(os.availableMemory ? { mem: bytesToGb(os.freemem()) } : {}).length
    ? bytesToGb(freeBytes) : null;
  // Aggregate disk free across mounted drives is non-trivial without shell; report RAM-equivalent as a safe lower bound.
  const tempMb = await tempDirSizeMB();
  const gpus = await gpuNames();
  const topProcs = await topProcesses();

  return {
    hostname: os.hostname(),
    ram_gb: Math.round(bytesToGb(totalBytes) * 10) / 10,
    gpu: gpus,
    local_model: process.env.LOCAL_MODEL || "qwen/qwen3-1.7b",
    memPct: usedPct,
    diskFreeGb,
    tempMb,
    topProcs,
  };
}

/**
 * Run an os-agent maintenance pass: gather health, apply safe optimization
 * (temp cleanup) when above threshold, and update the learning memory.
 */
export async function runMaintenance({ reportOnly = false } = {}) {
  const health = await collectHealth();
  await ensureMemoryFile();
  const mem = await readMemory();

  mem.system.hostname = health.hostname;
  mem.system.ram_gb = health.ram_gb;
  mem.system.gpu = health.gpu;
  mem.system.local_model = health.local_model;

  mem.health.last_check = nowIso();
  mem.health.last_memory_used_pct = health.memPct;
  mem.health.last_temp_mb = Math.round(health.tempMb);

  // Apply temp cleanup only when above 100 MB and not report-only.
  if (!reportOnly && health.tempMb > 100) {
    const before = health.tempMb;
    await cleanupTemp();
    const after = await tempDirSizeMB();
    const freed = Math.max(0, Math.round(before - after));
    if (freed > 0) {
      mem.optimizations.push({
        date: nowIso(),
        action: "temp-cleanup",
        detail: "Cleaned user temp folder",
        freed_mb: freed,
        impact: `Freed ${freed} MB of disk space`,
      });
    }
  }

  // Critical memory warning.
  if (health.memPct >= 85) {
    mem.learnings.push({
      date: nowIso(),
      topic: "memory",
      insight: `Critical memory usage detected (${health.memPct}% used).`,
      recommendation: "Close or reduce memory-heavy applications or upgrade RAM.",
    });
  }

  await fs.writeFile(MEMORY_FILE, JSON.stringify(mem, null, 2), "utf8");

  return {
    memPct: health.memPct,
    diskFreeGb: health.diskFreeGb,
    tempMb: Math.round(health.tempMb),
    optimizations: mem.optimizations.length,
    topProcs: health.topProcs,
  };
}
